mapper.select:
SELECT DEMANDS_ID,DEMANDS_NAME,DEMANDS_CONTENT,"RANK",DEMANDS_USER,DEVELOPER,COMPLETION_RATE,STATUS,DEMANDS_CONFIRM_DATE ,DEMANDS_FORECAST_DATE,START_DATE,COMPLETE_DATE,REMARK,UPDATE_TIME,UPDATE_USER FROM A1MFG.REPORTING_DEMANDS_LIST WHERE 1=1
AND DEMANDS_ID = #{demandsId}
AND DEMANDS_NAME LIKE CONCAT('%',#{demandsName},'%')
AND DEVELOPER LIKE CONCAT('%',#{developer},'%')
AND STATUS = #{status}
AND COMPLETE_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-90,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD')

mapper.insert:
INSERT INTO A1MFG.REPORTING_DEMANDS_LIST (DEMANDS_ID, DEMANDS_NAME, DEMANDS_CONTENT, "RANK", DEMANDS_USER, DEVELOPER, COMPLETION_RATE, STATUS, DEMANDS_CONFIRM_DATE
, DEMANDS_FORECAST_DATE, START_DATE, COMPLETE_DATE, REMARK, UPDATE_TIME, UPDATE_USER)
VALUES (#{demandsId,javaType=String,jdbcType=VARCHAR}, #{demandsName,javaType=String,jdbcType=VARCHAR}
, #{demandsContent,javaType=String,jdbcType=VARCHAR}, #{rank,javaType=_integer,jdbcType=INTEGER}, #{demandsUser,javaType=String,jdbcType=VARCHAR}
, #{developer,javaType=String,jdbcType=VARCHAR}, #{completionRate,javaType=String,jdbcType=VARCHAR}, #{status,javaType=String,jdbcType=VARCHAR}
, #{demandsConfirmDate,javaType=String,jdbcType=VARCHAR}, #{demandsForecastDate,javaType=String,jdbcType=VARCHAR}
, #{startDate,javaType=String,jdbcType=VARCHAR}, #{completeDate,javaType=String,jdbcType=VARCHAR}, #{remark,javaType=String,jdbcType=VARCHAR}
, SYSDATE, #{updateUser,javaType=String,jdbcType=VARCHAR})
